<?php
require __DIR__.'/config.php';$pdo=db();$cart=$_SESSION['cart']??[];if(!$cart){header('Location: cart.php');exit;}verify_csrf();
$ids=array_map('intval',array_keys($cart));$in=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM products WHERE active=1 AND id IN ($in)");$s->execute($ids);$items=$s->fetchAll();$subtotal=0;foreach($items as $p)$subtotal+=(float)$p['price']*(int)$cart[$p['id']];
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');$notes=trim($_POST['notes']??'');
 if($name===''||$phone===''||$address==='')$error='Please fill in your name, phone number and delivery address.';
 else try{$pdo->beginTransaction();$code='AS'.date('ymd').strtoupper(bin2hex(random_bytes(3)));$fee=60;$total=$subtotal+$fee;
 $s=$pdo->prepare("INSERT INTO orders(order_code,customer_name,phone,address,subtotal,delivery_fee,total,payment_method,status,notes) VALUES(?,?,?,?,?,?,?,'COD','Pending',?)");$s->execute([$code,$name,$phone,$address,$subtotal,$fee,$total,$notes]);$oid=(int)$pdo->lastInsertId();
 $ins=$pdo->prepare("INSERT INTO order_items(order_id,product_id,product_name,unit,price,quantity) VALUES(?,?,?,?,?,?)");$stock=$pdo->prepare("UPDATE products SET stock=stock-? WHERE id=? AND stock>=?");
 foreach($items as $p){$qty=(int)$cart[$p['id']];$stock->execute([$qty,$p['id'],$qty]);if(!$stock->rowCount())throw new RuntimeException('Some items are no longer in stock. Please update your cart.');$ins->execute([$oid,$p['id'],$p['name'],$p['unit'],$p['price'],$qty]);}
 $pdo->commit();unset($_SESSION['cart']);header('Location: order-success.php?code='.urlencode($code));exit;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Could not place the order. Please try again.';}
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Checkout — Aastha</title><link rel="stylesheet" href="assets/css/store.css"></head><body><header class="simple-head wrap"><a class="brand" href="index.php"><span class="brand-mark">A</span><span>Aastha<small>FRESH EVERY DAY</small></span></a><a href="cart.php">← Back to cart</a></header><main class="wrap page-main"><span class="eyebrow">ALMOST THERE</span><h1>Checkout</h1><?php if($error): ?><div class="notice error"><?=e($error)?></div><?php endif; ?><div class="checkout-grid"><form class="checkout-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><h2>Delivery details</h2><label>Full name<input name="name" required value="<?=e($_POST['name']??'')?>"></label><label>Mobile number<input name="phone" required inputmode="tel" value="<?=e($_POST['phone']??'')?>"></label><label>Delivery address<textarea name="address" required rows="3"><?=e($_POST['address']??'')?></textarea></label><label>Order note (optional)<textarea name="notes" rows="2"><?=e($_POST['notes']??'')?></textarea></label><h2>Payment method</h2><div class="payment-choice"><b>Cash on delivery (COD)</b><small>Pay in cash when your order arrives.</small></div><button class="green-btn full">Place order · <?=money($subtotal+60)?></button></form><aside class="summary"><h2>Your order</h2><?php foreach($items as $p): ?><p><span><?=e($p['name'])?> × <?=(int)$cart[$p['id']]?></span><b><?=money((float)$p['price']*(int)$cart[$p['id']])?></b></p><?php endforeach; ?><hr><p><span>Subtotal</span><b><?=money($subtotal)?></b></p><p><span>Delivery fee</span><b><?=money(60)?></b></p><div class="summary-total"><span>Total</span><b><?=money($subtotal+60)?></b></div></aside></div></main></body></html>